import{_ as i,o as t,c as r,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"Thèse centrale de l'anti-prédationisme","description":"","frontmatter":{},"headers":[],"relativePath":"fr/04-反掠夺主义核心论纲.md","filePath":"fr/04-反掠夺主义核心论纲.md","lastUpdated":null}`),a={name:"fr/04-反掠夺主义核心论纲.md"};function n(o,e,l,d,u,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="these-centrale-de-l-anti-predationisme" tabindex="-1">Thèse centrale de l&#39;anti-prédationisme <a class="header-anchor" href="#these-centrale-de-l-anti-predationisme" aria-label="Permalink to &quot;Thèse centrale de l&#39;anti-prédationisme&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>04</td></tr><tr><td>Module</td><td>Principes généraux et paramètres fondamentaux</td></tr><tr><td>Mots-clés</td><td>Anti-prédation, Critique de la prédation, Alternative symbiotique, Ligne rouge éthique, Révolution systémique</td></tr></tbody></table><h2 id="i-definition-et-manifestations-du-predationisme" tabindex="-1">I. Définition et manifestations du prédationisme <a class="header-anchor" href="#i-definition-et-manifestations-du-predationisme" aria-label="Permalink to &quot;I. Définition et manifestations du prédationisme&quot;">​</a></h2><p>Le prédationisme est une vision cosmique et un système de culture qui prend pour moyens centraux l&#39;appropriation sans compensation, la dévoration et l&#39;exploitation de l&#39;Origine, de l&#39;énergie, de la fortune et des ressources d&#39;autres vies ou plans, dans le but de réaliser sa propre évolution ou celle de son groupe. Le prédationisme n&#39;est pas une technique de culture spécifique, mais une position fondamentale traversant la philosophie de culture, les institutions sociales et les relations civilisationnelles.</p><p>Dans l&#39;histoire de Heng Yuan Zhou, le prédationisme s&#39;est manifesté sous les principales formes suivantes :</p><table tabindex="0"><thead><tr><th>Forme</th><th>Manifestation</th><th>Préjudice</th></tr></thead><tbody><tr><td>Prédation d&#39;énergie</td><td>Dévorer directement l&#39;énergie de culture ou l&#39;Origine d&#39;autres vies</td><td>Provoque la mort du prédaté ou la perte totale de sa culture ; la circulation d&#39;énergie cosmique est rompue</td></tr><tr><td>Prédation de fortune</td><td>Voler la fortune d&#39;autrui ou de races entières par des arts secrets</td><td>Provoque l&#39;effondrement du destin du prédaté et le déclin racial</td></tr><tr><td>Monopole des méthodes</td><td>Quelques sectes monopolisent les méthodes de culture, échangeant la transmission contre loyauté et ressources</td><td>Provoque la solidification des classes ; les êtres inférieurs perdent leurs voies d&#39;évolution</td></tr><tr><td>Colonisation de plans</td><td>Des plans supérieurs conquièrent des plans inférieurs, pillant leurs ressources et populations</td><td>Endommage la membrane du plan et effondre les écosystèmes du plan</td></tr><tr><td>Asservissement spirituel</td><td>Transformer d&#39;autres vies en outils de culture par le contrôle de l&#39;âme</td><td>Prive l&#39;asservi du libre arbitre, violant la dignité de la vie</td></tr><tr><td>Épuisement des ressources</td><td>Exploitation sans retenue des ressources d&#39;une planète ou d&#39;un plan</td><td>Provoque l&#39;extinction écologique et l&#39;accélération de l&#39;entropie cosmique</td></tr></tbody></table><h2 id="ii-les-erreurs-fondamentales-du-predationisme" tabindex="-1">II. Les erreurs fondamentales du prédationisme <a class="header-anchor" href="#ii-les-erreurs-fondamentales-du-predationisme" aria-label="Permalink to &quot;II. Les erreurs fondamentales du prédationisme&quot;">​</a></h2><p>L&#39;anti-prédationisme considère que le prédationisme comporte trois erreurs fondamentales :</p><h3 id="_2-1-erreur-de-vision-cosmique-traiter-l-univers-comme-un-terrain-de-chasse-fini" tabindex="-1">2.1 Erreur de vision cosmique : traiter l&#39;univers comme un terrain de chasse fini <a class="header-anchor" href="#_2-1-erreur-de-vision-cosmique-traiter-l-univers-comme-un-terrain-de-chasse-fini" aria-label="Permalink to &quot;2.1 Erreur de vision cosmique : traiter l&#39;univers comme un terrain de chasse fini&quot;">​</a></h3><p>La vision cosmique prédatrice considère l&#39;univers comme un terrain de chasse aux ressources finies, croyant que l&#39;évolution doit être un jeu à somme nulle et que l&#39;ascension du fort doit se faire au prix du sacrifice du faible. Cette vision ignore l&#39;« évolutivité » de l&#39;univers lui-même — l&#39;univers n&#39;est pas un contenant statique de ressources, mais un être vivant capable d&#39;ascension dimensionnelle globale par la symbiose ordonnée. Lorsque les prédateurs dévorent les faibles, ils consomment non seulement l&#39;énergie des faibles, mais le potentiel évolutif de l&#39;univers tout entier.</p><h3 id="_2-2-erreur-ethique-placer-le-droit-a-l-evolution-du-fort-au-dessus-du-droit-a-la-survie-du-faible" tabindex="-1">2.2 Erreur éthique : placer le droit à l&#39;évolution du fort au-dessus du droit à la survie du faible <a class="header-anchor" href="#_2-2-erreur-ethique-placer-le-droit-a-l-evolution-du-fort-au-dessus-du-droit-a-la-survie-du-faible" aria-label="Permalink to &quot;2.2 Erreur éthique : placer le droit à l&#39;évolution du fort au-dessus du droit à la survie du faible&quot;">​</a></h3><p>Le prédationisme prend « le fort dévore le faible » pour loi naturelle, croyant que le fort a le droit et même le devoir de dévorer le faible. Cette vision éthique confond la sélection naturelle et le choix moral. Dans la nature, le fort dévorant le faible est une loi écologique inconsciente ; mais dans les civilisations de culture conscientes, le fort possède la capacité de choisir et porte donc la responsabilité du choix. La prédation déguisée en « Voie du Ciel » est essentiellement le fort présentant sa propre cupidité comme loi cosmique.</p><h3 id="_2-3-erreur-d-efficacite-croire-que-la-predation-est-la-voie-d-evolution-la-plus-rapide" tabindex="-1">2.3 Erreur d&#39;efficacité : croire que la prédation est la voie d&#39;évolution la plus rapide <a class="header-anchor" href="#_2-3-erreur-d-efficacite-croire-que-la-predation-est-la-voie-d-evolution-la-plus-rapide" aria-label="Permalink to &quot;2.3 Erreur d&#39;efficacité : croire que la prédation est la voie d&#39;évolution la plus rapide&quot;">​</a></h3><p>Le prédationisme prétend que la prédation est la voie d&#39;évolution la plus rapide et la plus efficace. Pourtant, à long terme, l&#39;évolution prédatrice souffre d&#39;un sérieux « plafond d&#39;efficacité » : premièrement, l&#39;énergie obtenue par prédation porte souvent la volonté résiduelle de son propriétaire d&#39;origine, exigeant d&#39;énormes efforts de raffinage et de purification ; deuxièmement, les actes prédateurs provoquent la résistance des prédatés et de leurs groupes affiliés, augmentant les coûts externes de la culture ; troisièmement, la dépendance à long terme à la prédation dégrade la capacité d&#39;évolution fondée sur l&#39;Origine du cultivateur, le conduisant à la stagnation une fois la proie indisponible ; quatrièmement, les cultivateurs prédateurs font souvent face au goulot d&#39;étranglement de l&#39;« Origine impure » lors de la percée vers le niveau suprême, rendant difficile l&#39;accès véritable à l&#39;Origine cosmique.</p><h2 id="iii-propositions-centrales-de-l-anti-predationisme" tabindex="-1">III. Propositions centrales de l&#39;anti-prédationisme <a class="header-anchor" href="#iii-propositions-centrales-de-l-anti-predationisme" aria-label="Permalink to &quot;III. Propositions centrales de l&#39;anti-prédationisme&quot;">​</a></h2><p>L&#39;anti-prédationisme ne nie pas simplement toute compétition et toute différence, mais propose les propositions centrales suivantes :</p><ol><li><strong>L&#39;évolution peut être non-somme-nulle</strong> : par les cycles symbiotiques et le réseau d&#39;ancres, l&#39;évolution des Dix Mille Races peut produire des effets synergiques, réalisant une efficacité évolutive où le tout dépasse la somme des parties.</li><li><strong>La compétition doit être créative plutôt que destructive</strong> : l&#39;anti-prédationisme ne s&#39;oppose pas à la compétition saine, mais la compétition doit prendre la forme d&#39;une amélioration de sa propre capacité créative plutôt que de l&#39;élimination de la capacité prédatrice de l&#39;adversaire.</li><li><strong>La responsabilité du fort est supérieure à ses droits</strong> : plus le niveau d&#39;un cultivateur est élevé, plus sa responsabilité envers le réseau symbiotique est grande, et non plus grand son droit de prédater. Les cultivateurs avancés ont l&#39;obligation de guider les cultivateurs juniors, de maintenir la stabilité des ancres et de protéger la sécurité civilisationnelle.</li><li><strong>Les ressources doivent être augmentées par la création plutôt que distribuées par la prédation</strong> : l&#39;approche centrale de la civilisation symbiotique est d&#39;agrandir le gâteau plutôt que de le diviser, créant continuellement de nouvelles ressources de culture par le progrès technologique et l&#39;application des lois.</li><li><strong>L&#39;anti-prédation n&#39;est pas l&#39;égalitarisme</strong> : l&#39;anti-prédationisme s&#39;oppose à la prédation sans travail, non aux différences issues d&#39;À Chacun Selon son Travail. La civilisation symbiotique reconnaît les différences de résultats évolutifs, mais insiste sur le fait que les différences doivent provenir de l&#39;effort et de la contribution personnels.</li></ol><h2 id="iv-garanties-institutionnelles-de-l-anti-predationisme" tabindex="-1">IV. Garanties institutionnelles de l&#39;anti-prédationisme <a class="header-anchor" href="#iv-garanties-institutionnelles-de-l-anti-predationisme" aria-label="Permalink to &quot;IV. Garanties institutionnelles de l&#39;anti-prédationisme&quot;">​</a></h2><p>L&#39;anti-prédationisme n&#39;est pas seulement une proposition théorique ; il dispose d&#39;une série de garanties institutionnelles :</p><ul><li><strong>Garantie juridique</strong> : la Constitution Symbiotique et la loi anti-monopole interdisent explicitement le comportement prédateur ; le Tribunal Symbiotique a compétence sur les affaires de prédation</li><li><strong>Garantie mécanique</strong> : le Système de Contrat Lié à la Production garantit que la distribution des ressources repose sur la contribution plutôt que sur la violence ; le réseau d&#39;ancres surveille les flux d&#39;énergie anormaux</li><li><strong>Garantie systémique</strong> : les Trois Cents Systèmes de Culture de l&#39;Origine reposent tous sur les principes de circulation symbiotique ; aucune méthode prédatrice n&#39;existe</li><li><strong>Garantie éducative</strong> : le Système d&#39;Éducation Symbiotique fait de l&#39;éthique anti-prédation une matière obligatoire, éradiquant la pensée prédatrice à sa racine</li><li><strong>Garantie de supervision</strong> : l&#39;Assemblée de la République des Dix Mille Races a créé un Comité anti-prédation, chargé de superviser et d&#39;enquêter sur les comportements prédateurs</li></ul><h2 id="v-politique-envers-les-forces-predatrices-residuelles" tabindex="-1">V. Politique envers les forces prédatrices résiduelles <a class="header-anchor" href="#v-politique-envers-les-forces-predatrices-residuelles" aria-label="Permalink to &quot;V. Politique envers les forces prédatrices résiduelles&quot;">​</a></h2><p>Pour les forces prédatrices résiduelles encore présentes dans l&#39;univers, la civilisation symbiotique adopte une politique d&#39;« isolement, transformation et sanction » : les prédateurs qui n&#39;ont pas encore causé de préjudice grave reçoivent une éducation éthique et une transformation systémique, les guidant à rejoindre le système symbiotique ; les prédateurs qui refusent la transformation et continuent de nuire à l&#39;ordre symbiotique sont soumis à l&#39;isolement du plan et à des restrictions de culture ; les prédateurs ayant causé des catastrophes majeures sont sanctionnés conformément à la loi. La civilisation symbiotique ne préconise pas de combattre la prédation par la prédation ; toutes les sanctions doivent passer par le procès équitable du Tribunal Symbiotique.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;anti-prédationisme est l&#39;une des pierres angulaires théoriques de la Civilisation Symbiotique de l&#39;Ancre. Ce n&#39;est pas seulement une critique de l&#39;ancien système prédateur, mais une construction positive de la possibilité de l&#39;évolution symbiotique. L&#39;objectif ultime de l&#39;anti-prédationisme n&#39;est pas d&#39;éliminer les forts, mais de faire servir la puissance des forts à l&#39;évolution commune des Dix Mille Races.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Déclaration de la Civilisation Symbiotique de l&#39;Ancre)</li><li>03-共生文明宪章 (Charte de la Civilisation Symbiotique)</li><li>19-修炼伦理与边界 (Éthique de culture et limites)</li></ul>',26)])])}const f=i(a,[["render",n]]);export{m as __pageData,f as default};
